using System.Text.Json;
using NAudio.CoreAudioApi;
using NAudio.Wave;
using NAudio.Wave.SampleProviders;
namespace OpenEQ;
internal static class NativeClientChecks {
 public static int Run(string path,string name){var report=new Dictionary<string,object>();var results=new List<object>();bool success=true;NativeApo? controller=null;try{var target=AudioEngine.Devices().Single(d=>d.Name.Contains(name,StringComparison.OrdinalIgnoreCase));bool native=NativeApo.Installed(target.Id);report["device"]=target;report["native_bound"]=native;report["sessions_before"]=AudioDiagnostics.Read();if(native){var flat=Preset.Flat();flat.Bands.Clear();flat.Output.Protection=false;controller=new NativeApo(target.Id,flat,false);}using var enumerator=new MMDeviceEnumerator();using var device=enumerator.GetDevice(target.Id);report["mix_format"]=device.AudioClient.MixFormat.ToString();
   void Exercise(string label,Func<IWavePlayer> make,int rate,bool pcm){IWavePlayer? player=null;try{long before=controller?.Frames??0;player=make();var tone=new SignalGenerator(rate,2){Frequency=440,Gain=.001};IWaveProvider provider=pcm?new SampleToWaveProvider16(tone):new SampleToWaveProvider(tone);player.Init(provider);player.Play();Thread.Sleep(700);bool advanced=controller==null||controller.Frames>before;player.Stop();if(!advanced)throw new Exception("播放接口启动，但原生 APO 未执行");results.Add(new{api=label,result="PASS",rate,format=provider.WaveFormat.ToString(),native_frames=controller==null?0:controller.Frames-before});}catch(Exception e){success=false;results.Add(new{api=label,result="FAIL",hresult=e.HResult.ToString("X8"),exception=e.ToString()});}finally{player?.Dispose();Thread.Sleep(100);}}
   Exercise("WASAPI shared float",()=>new WasapiOut(device,AudioClientShareMode.Shared,true,200),device.AudioClient.MixFormat.SampleRate,false);
   var direct=DirectSoundOut.Devices.Where(d=>d.Description.Contains(name,StringComparison.OrdinalIgnoreCase)).ToArray();report["directsound_devices"]=DirectSoundOut.Devices.Select(d=>new{d.Guid,d.Description}).ToArray();Exercise("DirectSound 44.1k PCM16",()=>new DirectSoundOut(direct.Length==1?direct[0].Guid:throw new Exception("DirectSound 未唯一枚举到物理设备"),200),44100,true);
   var wave=Enumerable.Range(0,WaveOut.DeviceCount).Select(n=>new{number=n,name=WaveOut.GetCapabilities(n).ProductName}).ToArray();report["waveout_devices"]=wave;Exercise("WaveOut 44.1k PCM16",()=>new WaveOutEvent{DeviceNumber=wave.Single(d=>d.name.Contains(name,StringComparison.OrdinalIgnoreCase)).number,DesiredLatency=200},44100,true);
   report["result"]=success?"PASS":"FAIL";return success?0:1;
  }catch(Exception e){report["result"]="FAIL";report["exception"]=e.ToString();return 1;}finally{controller?.Dispose();report["cases"]=results;report["scope"]="Three real Windows playback APIs with a quiet generated tone, physical endpoint selected explicitly; no format, default route or binding changes. Not a music listening verdict.";File.WriteAllText(path,JsonSerializer.Serialize(report,new JsonSerializerOptions{WriteIndented=true,Encoder=System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping}));}}
}
